param([Parameter(Mandatory=$true)][string[]]$Roots,[Parameter(Mandatory=$true)][string]$ReportDir)
$ErrorActionPreference='Stop'
$rootsResolved=@(); foreach($r in $Roots){ $p=(Resolve-Path -LiteralPath $r).Path.TrimEnd('\'); if($p -match '^[A-Za-z]:\\(Windows|Program Files(?: \(x86\))?|ProgramData)(\\|$)' -or $p -match '^[A-Za-z]:\\Users\\[^\\]+$'){throw "Disallowed root: $p"}; $rootsResolved += $p }
$rootsResolved=@($rootsResolved | Select-Object -Unique)
$report=[IO.Path]::GetFullPath($ReportDir); foreach($r in $rootsResolved){if($r.StartsWith($report+'\',[StringComparison]::OrdinalIgnoreCase) -or $r -eq $report){throw 'Report directory must not contain a scan root'}}
New-Item -ItemType Directory -Path $report -Force | Out-Null
$files=New-Object 'System.Collections.Generic.List[object]'; $dirs=New-Object 'System.Collections.Generic.List[object]'; $errors=New-Object 'System.Collections.Generic.List[string]'
function Walk([string]$path){
  try{$children=Get-ChildItem -LiteralPath $path -Force -ErrorAction Stop}catch{$errors.Add("$path : $($_.Exception.Message)");return}
  foreach($x in $children){
    if($x.FullName.StartsWith($report+'\',[StringComparison]::OrdinalIgnoreCase) -or $x.FullName -eq $report){continue}
    if(($x.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0){$errors.Add("Reparse/cloud item skipped: $($x.FullName)");continue}
    if($x.PSIsContainer){$dirs.Add([pscustomobject]@{Path=$x.FullName;Bytes=[int64]0});Walk $x.FullName}
    else{$files.Add([pscustomobject]@{Path=$x.FullName;Bytes=[int64]$x.Length;ModifiedUtc=$x.LastWriteTimeUtc.ToString('o');Hash='';Category='Unknown';Risk='Unknown'})}
  }
}
foreach($r in $rootsResolved){$dirs.Add([pscustomobject]@{Path=$r;Bytes=[int64]0});Walk $r}
function Category([string]$p){$s=$p.ToLowerInvariant(); if($s -match '\.git\\|\.env$|id_rsa|\.pem$|\.key$|\.venv\\|node_modules\\|\.pt$|\.pth$|\.safetensors$|\.ckpt$'){return 'Important retain'}; if($s -match 'lecture|notes|vorlesung'){return 'Lecture Notes'};if($s -match 'assignment|homework|uebung|übung'){return 'Assignments'};if($s -match 'exam|klausur'){return 'Exams'};if($s -match 'research|paper|thesis'){return 'Research'};if($s -match 'machine.learning|\bml\b|ai-|neural'){return 'AI/ML'};if($s -match 'math|mathe|algebra|calculus'){return 'Mathematics'};if($s -match 'internship|praktikum'){return 'Internships'};if($s -match 'application|bewerbung'){return 'Applications'};if($s -match 'course|semester|university|uni\\'){return 'University Courses'};if($s -match '\.(ps1|py|js|ts|java|cpp|rs|go)$'){return 'Coding Projects'};if($s -match '\.(zip|7z|rar|tar|gz)$'){return 'Archives'};if($s -match '\\downloads\\'){return 'Downloads'};return 'Unknown'}
foreach($f in $files){$f.Category=Category $f.Path}
$groups=@($files | Group-Object Bytes | Where-Object Count -gt 1);$dups=New-Object 'System.Collections.Generic.List[object]';$gid=0
foreach($g in $groups){$hashes=@{};foreach($f in $g.Group){try{$f.Hash=(Get-FileHash -LiteralPath $f.Path -Algorithm SHA256 -ErrorAction Stop).Hash; if(!$hashes.ContainsKey($f.Hash)){$hashes[$f.Hash]=New-Object 'System.Collections.Generic.List[object]'};$hashes[$f.Hash].Add($f)}catch{$errors.Add("Hash failed: $($f.Path) : $($_.Exception.Message)")}};foreach($h in $hashes.Keys){if($hashes[$h].Count -lt 2){continue};$gid++;foreach($f in $hashes[$h]){$dups.Add([pscustomobject]@{Group=$gid;Path=$f.Path;Bytes=$f.Bytes;SHA256=$h;PotentialLogicalSavingsBytes=($hashes[$h].Count-1)*$f.Bytes;PhysicalSavings='Unknown: hard-link identity not verified';Risk='Manual review'})}}}
$dirBytes=New-Object 'System.Collections.Generic.Dictionary[string,long]' ([StringComparer]::OrdinalIgnoreCase)
foreach($d in $dirs){$dirBytes[$d.Path]=0}
foreach($f in $files){$parent=[IO.Path]::GetDirectoryName($f.Path);while($parent -and $dirBytes.ContainsKey($parent)){$dirBytes[$parent]+=$f.Bytes;$next=[IO.Path]::GetDirectoryName($parent);if($next -eq $parent){break};$parent=$next}}
foreach($d in $dirs){$d.Bytes=$dirBytes[$d.Path]}
$large=@($files | Sort-Object Bytes -Descending | Select-Object -First 20 @{n='Type';e={'File'}},Path,Bytes,Category);$large += @($dirs | Sort-Object Bytes -Descending | Select-Object -First 20 @{n='Type';e={'Folder'}},Path,Bytes,@{n='Category';e={'n/a'}})
$large | Export-Csv -LiteralPath (Join-Path $report 'large_files.csv') -NoTypeInformation -Encoding UTF8
$dups | Export-Csv -LiteralPath (Join-Path $report 'duplicate_files.csv') -NoTypeInformation -Encoding UTF8
$candidates=New-Object 'System.Collections.Generic.List[object]';foreach($f in $files){$p=$f.Path.ToLowerInvariant();$why='';if($p -match '\\__pycache__\\|\.pyc$|\\dist\\|\\build\\'){$why='Regenerable build/cache candidate'}elseif($p -match '\.(msi|exe)$' -and $p -match '\\downloads\\'){$why='Downloaded installer; verify need'}elseif($p -match '\.(zip|7z|rar)$' -and $f.Bytes -ge 100MB){$why='Large archive; verify contents and backup'};if($why -and $f.Category -ne 'Important retain'){$candidates.Add([pscustomobject]@{Path=$f.Path;Bytes=$f.Bytes;Reason=$why;Risk='Manual review';Status='Preview only'})}}
$candidates | Export-Csv -LiteralPath (Join-Path $report 'cleanup_candidates.csv') -NoTypeInformation -Encoding UTF8
$vols=@($rootsResolved | ForEach-Object {[IO.Path]::GetPathRoot($_)} | Select-Object -Unique);$disk=@();foreach($v in $vols){try{$di=New-Object IO.DriveInfo($v);$disk+= "$v capacity $($di.TotalSize) bytes; free $($di.AvailableFreeSpace) bytes"}catch{$errors.Add("Disk info unavailable: $v")}}
$total=($files | Measure-Object Bytes -Sum).Sum;if(!$total){$total=0};$manual=($candidates | Measure-Object Bytes -Sum).Sum;if(!$manual){$manual=0};$retain=($files | Where-Object Category -eq 'Important retain' | Measure-Object Bytes -Sum).Sum;if(!$retain){$retain=0}
$overview=@('# Disk overview','',"Scanned: $(Get-Date -Format o)","Roots: $($rootsResolved -join ', ')",'',"Disk: $($disk -join '; ')","Scanned logical bytes: $total","Safe-to-consider cleanup bytes: 0 (no candidate verified safe)","Manual-review candidate bytes: $manual (may overlap duplicates)","Organization-only bytes: $total (upper bound; moving releases no space)","Important-to-retain identified bytes: $retain", "Files: $($files.Count); folders: $($dirs.Count); duplicate groups: $gid",'', '## Largest files', '');$overview+=@($large | Where-Object Type -eq File | Select-Object -First 20 | ForEach-Object {"- $($_.Bytes) bytes — $($_.Path)"});$overview+=@('','## Largest folders','');$overview+=@($large | Where-Object Type -eq Folder | Select-Object -First 20 | ForEach-Object {"- $($_.Bytes) bytes — $($_.Path)"});$overview+=@('','## Limits','');$overview+=@($errors | Select-Object -First 100);$overview | Set-Content -LiteralPath (Join-Path $report 'disk_overview.md') -Encoding UTF8
$cats=$files | Group-Object Category | Sort-Object Count -Descending;$plan=@('# Organization plan','','Preview only; no files moved. Suggested categories and logical bytes:','');$plan+=@($cats | ForEach-Object {"- $($_.Name): $(($_.Group | Measure-Object Bytes -Sum).Sum) bytes ($($_.Count) files)"});$plan+=@('','Suggested Archive/University/<course>/<year>, Archive/Projects/<project>/<version>, Archive/Downloads/<year>. All source-to-destination moves require a reviewed full-path manifest and explicit approval.','',"Unknown files: $(($files | Where-Object Category -eq 'Unknown').Count); no cleanup inferred from age.");$plan | Set-Content -LiteralPath (Join-Path $report 'organization_plan.md') -Encoding UTF8
Write-Output "Audit complete: $report; files=$($files.Count); folders=$($dirs.Count); duplicate_groups=$gid; errors=$($errors.Count)"
